// Ambient module declarations for the virtual modules generated by the Vite plugin.

// Exports are DurableObject subclasses with names derived from database filenames
// (e.g. main.ts -> MainDatabaseDO).
declare module "virtual:durable-db/__durableObjects";

// Dev-epoch helpers baked in at build time. `applyDevEpoch` suffixes instance
// keys with the database's dev epoch — its own after `db reset --database`,
// else the project's (identity in production builds).
declare module "virtual:durable-db/__devEpoch" {
  export const devEpoch: string | null;
  export const devEpochs: Record<string, string>;
  export function applyDevEpoch(key: string, dbName?: string): string;
}

// The databases the plugin discovered, each with its tables (the schema
// module's own objects) — for a library that maps a table to its database.
declare module "virtual:durable-db/__databases" {
  export const databases: ReadonlyArray<{
    name: string;
    bindingName: string;
    className: string;
    instance: 'per-tenant' | 'global';
    schema: Record<string, unknown>;
  }>;
}

/** @deprecated Use "virtual:durable-db/__durableObjects" instead. */
declare module "virtual:eagerpatch/durable-db/__durableObjects";
